/* @lc app=leetcode id=3988 lang=kotlin */ class Solution { fun blk(m: Int, n: Int, k: Int): List<String>? = if (m < 2 || n < k) null else (0 until m).map { i -> (0 until n).joinToString("") { j -> if ((i <= 1 && (i == 1 || j < k)) || (j == n - 1 && i >= 1)) "." else "#" } } fun createGrid(m: Int, n: Int, k: Int): Array<String> = (if (k == 1) (0 until m).map { i -> (0 until n).joinToString("") { j -> if (i == 0 || j == n - 1) "." else "#" } } else blk(m, n, k) ?: blk(n, m, k)?.let { g -> (0 until m).map { i -> (0 until n).joinToString("") { j -> g[j][i].toString() } } } ?: (if (k == 4 && m == 3 && n == 3) listOf("..#", "...", "#..") else emptyList())).toTypedArray() }